def extract_tickets(mex_json):
    out=[]
    for r in mex_json.get('results', []):
        d=(r.get('response', {}) or {}).get('data', {}) or {}
        out.extend(d.get('tickets', []) or [])
    return out

def dedupe_by_id(tickets):
    seen=set(); out=[]
    for t in tickets:
        tid=t.get('id')
        if tid is None or tid in seen: continue
        seen.add(tid); out.append(t)
    return out
